{
    "class": "AS3",
    "action": "deploy",
    "persist": true,
    "declaration": {
        "class": "ADC",
        "schemaVersion": "3.0.0",
        "id": "urn:uuid:33045210-3ab8-4636-9b2a-c98d22ab915d",
        "label": "Sample 1",
        "remark": "Simple MCP application",
        "Sample_01": {
            "class": "Tenant",
            "A1": {
                "class": "Application",
                "mySSEProfile": {
                    "class": "SSE_Profile"
                },
                "myJSONProfile": {
                    "class": "JSON_Profile"
                },
                "service": {
                    "class": "Service_HTTP",
                    "virtualAddresses": [
                        "10.0.1.10"
                    ],
                    "pool": "mcp_pool",
                    "iRules": [
                        "persistenceiRule"
                    ],
                    "persistenceMethods": [
                        "cookie"
                    ],
                    "proflieSSE": {
                        "use": "mySSEProfile"
                    },
                    "profileJSON": {
                        "use": "myJSONProfile"
                    }
                },
                "mcp_pool": {
                    "class": "Pool",
                    "monitors": [
                        "http"
                    ],
                    "members": [
                        {
                            "servicePort": 80,
                            "serverAddresses": [
                                "192.0.1.10",
                                "192.0.1.11"
                            ]
                        }
                    ]
                },
                "persistenceiRule": {
                    "class": "iRule",
                    "iRule": "when HTTP_REQUEST {
    set is_req_to_sse_endpoint false

    if { [HTTP::path] eq "/sse" } {
        # SSE endpoint for 2024-11-05 version of MCP Spec
        set is_req_to_sse_endpoint true
        return
    }

    if { [HTTP::path] eq "/messages" } {
        # Message endpoint for 2024-11-05 version of MCP Spec
        # Decode persist secret in URI of request
        set query_string [HTTP::query]
        set f5_sess_found false
        set new_query_string ""
        set query_separator ""
        set queries [split $query_string "&"]
        foreach query $queries {
            if { $f5_sess_found } {
                # On queries after the F5 session. Retain them.
                append new_query_string "${query_separator}${query}"
                set query_separator "&"
            } elseif { [string match "f5Session=*" $query] } {
                # Here's our persistence secret. Handle It.
                set pmbr_info [URI::decode [string range $query 10 end]]
                set pmbr_parts [split $pmbr_info ","]
                if { [llength $pmbr_parts] == 2} {
                    set pmbr_tuple [split [lindex $pmbr_parts 1] ":"]
                    if { [llength $pmbr_tuple] == 2 } {
                        # Found a valid pool record. Tell the proxy.
                        pool [lindex $pmbr_parts 0] member [lindex $pmbr_parts 1]
                        set f5_sess_found true
                    } else {
                        HTTP::respond 404 noserver
                        return
                    }
                } else {
                    HTTP::respond 404 noserver
                    return
                }
            } else {
                # Another query. Haven't found the F5 secret yet.
                # Append to query string we will forward.
                append new_query_string "${query_separator}${query}"
                set query_separator "&"
            }
        }
        if { $f5_sess_found } {
            HTTP::query $new_query_string
        } else {
            HTTP::respond 404 noserver
        }
        return
    }

    if { [HTTP::path] eq "/mcp" } {
        # MCP endpoint for 2025-03-26 version of MCP Spec
        if { [HTTP::header exists "Mcp-Session-Id"] } {
            # Decode persist secret in session header
            set header_value [HTTP::header "Mcp-Session-Id"]
            set header_parts [split $header_value ","]

            if { [llength $header_parts] == 3 } {
                set pmbr_tuple [split [lindex $header_parts 1] ":"]
                if { [llength $pmbr_tuple] == 2 } {
                    HTTP::header replace "Mcp-Session-Id" [lindex $header_parts 2]
                    pool [lindex $header_parts 0] member [lindex $header_parts 1]
                } else {
                    HTTP::respond 404 noserver
                }
            } else {
                HTTP:: respond 404 noserver
            }
        }
    }
}

when HTTP_RESPONSE {
    if { [HTTP::header exists "Mcp-Session-Id"] } {
        # Using session header - 2025-03-26 spec - insert persist secret

        # Get the current pool member's IP and port
        set pool_member [LB::server pool],[IP::remote_addr]:[TCP::remote_port]

        # Prepend the pool member IP and port to the header value
        set header_value [HTTP::header "Mcp-Session-Id"]
        set new_header_value "$pool_member,$header_value"
        HTTP::header replace "Mcp-Session-Id" $new_header_value
    }
}

when SSE_RESPONSE {
    if { $is_req_to_sse_endpoint && [SSE::field get event] eq "endpoint" } {
        # Server sending MCP message endpoint. Insert persist secret
        set sse_data [SSE::field get data]

        # Extract existing URI info from SSE endpoint data
        set old_path [URI::path $sse_data][URI::basename $sse_data]
        set old_queries [URI::query $sse_data]
        if { [string length $old_queries] == 0} {
            set query_separator ""
        } else {
            set query_separator "&"
        }

        # Create a new query param encoding current pool member's info
        set new_query "f5Session=[URI::encode [LB::server pool],[IP::remote_addr]:[TCP::remote_port]]"

        # Construct new full endpoint, inserting F5 session info
        set new_endpoint "${old_path}?${new_query}${query_separator}${old_queries}"
        SSE::field set data $new_endpoint
    }
}",
                    "expand": true
                }
            }
        }
    }
}
